import fs from 'node:fs';
const p='index.html';
let s=fs.readFileSync(p,'utf8');
const marker='/* MOMOIROBARA BOTANICAL UI V7 */';
// Always create a fresh commit so the workflow is triggered, even if V7 is already present.
// Do not duplicate the actual repair if it has already been applied.
if(!s.includes(marker)){
  s=s.replace(/<script[^>]*id="momo-targeted-repair-v6"[^>]*>[\s\S]*?<\/script>/gi,'');
  s=s.replace(/\/\* MOMOIROBARA TARGETED REPAIR V6 \*\/[\s\S]*?(?=<\/style>)/g,'');
  const css=`${marker}
.momo-botanical{position:relative}.momo-botanical::before{content:"";position:absolute;inset:7px;border:1px solid color-mix(in srgb,var(--a) 24%,transparent);border-radius:inherit;pointer-events:none}.momo-vine{position:absolute;pointer-events:none;z-index:0;width:72px;height:72px;opacity:.34}.momo-vine svg{width:100%;height:100%;overflow:visible;fill:none;stroke:var(--a);stroke-width:1.35;stroke-linecap:round;stroke-linejoin:round}.momo-vine path{stroke-dasharray:120;stroke-dashoffset:120;animation:momoVineDraw 2.4s ease forwards,momoVineSway 5s ease-in-out 2.4s infinite}.momo-vine .petal{fill:var(--a);stroke:none;transform-origin:center;animation:momoPetalPulse 4s ease-in-out infinite}@keyframes momoVineDraw{to{stroke-dashoffset:0}}@keyframes momoVineSway{0%,100%{transform:rotate(-1deg)}50%{transform:rotate(2deg)}}@keyframes momoPetalPulse{0%,100%{opacity:.35;transform:scale(.9)}50%{opacity:.75;transform:scale(1.08)}}.momo-floral-divider{height:18px;display:flex;align-items:center;gap:8px;color:var(--a);opacity:.5;pointer-events:none;overflow:hidden}.momo-floral-divider::before,.momo-floral-divider::after{content:"";height:1px;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--a) 35%,transparent));flex:1}.momo-floral-divider span{font-size:12px;animation:momoPetalPulse 3.8s ease-in-out infinite}.momo-flower-field{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}.momo-field-petal{position:absolute;color:var(--a);opacity:.16;font-size:13px;animation:momoFloat 9s ease-in-out infinite}.momo-field-petal:nth-child(2n){animation-duration:12s}.momo-field-petal:nth-child(3n){animation-duration:15s}@keyframes momoFloat{0%,100%{transform:translateY(12px) rotate(0deg);opacity:.08}50%{transform:translateY(-18px) rotate(20deg);opacity:.22}}`;
  s=s.replace(/<\/style>/i,css+'\n</style>');
  const js=`<script id="momo-botanical-ui-v7">(()=>{const A=(x,r=document)=>[...r.querySelectorAll(x)];const vine=()=>{const h=document.querySelector('.home-hero');if(!h||h.querySelector('.momo-vine'))return;h.classList.add('momo-botanical');const v=document.createElement('div');v.className='momo-vine';v.style.cssText='right:12px;top:10px';v.innerHTML='<svg viewBox="0 0 80 80"><path d="M8 68 C20 48 24 35 43 28 C55 23 62 15 68 5"/><path d="M28 43 C20 38 15 30 15 22"/><path d="M43 29 C48 38 57 42 67 40"/><ellipse class="petal" cx="15" cy="21" rx="5" ry="8" transform="rotate(-35 15 21)"/><ellipse class="petal" cx="67" cy="40" rx="5" ry="8" transform="rotate(65 67 40)"/></svg>';h.appendChild(v)};const divider=()=>A('.section-title,.library-title,.settings-title,.playlist-title').forEach(h=>{if(h.nextElementSibling?.classList.contains('momo-floral-divider'))return;const d=document.createElement('div');d.className='momo-floral-divider';d.innerHTML='<span>❀</span>';h.insertAdjacentElement('afterend',d)});const field=()=>{if(document.querySelector('.momo-flower-field'))return;const f=document.createElement('div');f.className='momo-flower-field';['·','✧','❋','✦','❈'].forEach((g,i)=>{const e=document.createElement('span');e.className='momo-field-petal';e.textContent=g;e.style.left=(10+i*19)+'%';e.style.top=(12+(i%3)*27)+'%';e.style.animationDelay=(-i*1.7)+'s';f.appendChild(e)});document.body.appendChild(f)};const init=()=>{vine();divider();field()};document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init()})()</script>`;
  s=s.replace(/<\/body>/i,js+'</body>');
  fs.writeFileSync(p,s,'utf8');
}
console.log('V7 botanical repair trigger');